import { useQuery } from '@tanstack/react-query';
import axios from 'axios';
import { CommunityResponse } from '~/entities/community/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { QueryOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { queries } from '~/shared/api/query-keys';
import { resultify } from '~/shared/lib/utils/resultify';

const getCmmntyManage = (id: string) => {
  return id && id !== 'new'
    ? resultify(axios.get<CommunityResponse>(`${API_URLS.cmmntyManage(id)}`))
    : { tbCmmntyMastr: {} };
};

export const useGetCmmntyManageQuery = (id: string, options?: QueryOptions<CommunityResponse, CBDCAxiosError>) => {
  return useQuery<CommunityResponse, CBDCAxiosError>({
    queryKey: queries.community.cmmntyManage({ id }).queryKey,
    queryFn: () => getCmmntyManage(id),
    ...options,
  });
};
